configuration.jsScript:
// 1. Clean foreign keys if any
msg.remove("m3Air");
msg.remove("m3LPG");
msg.remove("delta_CO2");

var routes = ["Valid_Telemetry"];

// 2. PT100 Temperature Spike & Open/Short Circuit Hardware Guard
if (msg.temperature != null) {
    var t = Double.parseDouble(msg.temperature.toString());
    if (t < -45.0 || t > 160.0) {
        // Block corrupted hardware spike (-200C or +850C) from polluting ts_kv database!
        return ["Sensor_Spike_Fault"];
    }
    routes.add("Temp_Route");
}

// 3. Power Meter Energy & TOU Route
if (msg.kwh != null || msg.kWh != null || msg.p_total != null) {
    routes.add("Energy_Route");
}

// 4. Contactor Runtime & Maintenance Route
if (msg.status != null || msg.run != null) {
    routes.add("Contactor_Route");
}

return routes;

